use ScratchByPHP\Session;
final class Comment implements \JsonSerializable { public function __construct(private array $data,private ?Session $session=null,private ?string $type=null,private ?string $resourceId=null){} public static function fromArray(array $d,?Session $s=null,?string $type=null,?string $rid=null):self{return new self($d,$s,$type,$rid);} public function id():string{return (string)($this->data['id']??'');} public function author():?string{return $this->data['author']['username']??$this->data['username']??null;} public function content():string{return (string)($this->data['content']??'');} public function createdAt():?string{return $this->data['datetime_created']??$this->data['created_at']??null;} public function parentId():?string{return isset($this->data['parent_id'])?(string)$this->data['parent_id']:null;} public function toArray():array{return $this->data;} public function toJson():string{return (string)json_encode($this->data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);} public function jsonSerialize():mixed{return $this->data;} public function reply(string $text):array{if(!$this->session)throw new \LogicException('Authenticated Session gerekir.');return match($this->type){'project'=>$this->session->project((string)$this->resourceId)->replyComment($text,$this->id()),'studio'=>$this->session->studio((string)$this->resourceId)->replyComment($text,$this->id()),'user'=>$this->session->user((string)$this->resourceId)->postComment($text,$this->id()),default=>throw new \LogicException('Comment resource türü bilinmiyor.')};} public function delete():array{if(!$this->session)throw new \LogicException('Authenticated Session gerekir.');return match($this->type){'project'=>$this->session->project((string)$this->resourceId)->deleteComment($this->id()),'studio'=>$this->session->studio((string)$this->resourceId)->deleteComment($this->id()),'user'=>$this->session->user((string)$this->resourceId)->deleteComment($this->id()),default=>throw new \LogicException('Comment resource türü bilinmiyor.')};} public function report():array{if(!$this->session)throw new \LogicException('Authenticated Session gerekir.');return match($this->type){'project'=>$this->session->project((string)$this->resourceId)->reportComment($this->id()),'studio'=>$this->session->studio((string)$this->resourceId)->reportComment($this->id()),'user'=>$this->session->user((string)$this->resourceId)->reportComment($this->id()),default=>throw new \LogicException('Comment resource türü bilinmiyor.')};} }
